```python
from flask import Flask, request

app = Flask(__name__)

filters = {}  # A dictionary to store all the custom filters


@app.route('/filters', methods=['POST'])
def create_filter():
    """
    Create a custom filter.

    This method creates a custom filter by accepting a filter name and conditions as input in JSON format.
    The filter name should be unique, and the conditions could be any valid conditions to filter the resources.

    Example request body:
    {
        "name": "filter1",
        "conditions": {
            "field1": "value1",
            "field2": "value2"
        }
    }

    Example response:
    {
        "message": "Filter created successfully"
    }
    """
    filter_data = request.json
    name = filter_data.get('name')
    conditions = filter_data.get('conditions')

    if name in filters:
        return {"message": "Filter already exists"}, 409  # Conflict if the filter already exists

    filters[name] = conditions
    return {"message": "Filter created successfully"}


@app.route('/filters/<filter_name>', methods=['PUT'])
def update_filter(filter_name):
    """
    Update a custom filter.

    This method updates an existing custom filter by accepting the updated conditions in JSON format.

    Example request body:
    {
        "conditions": {
            "field1": "new_value1",
            "field2": "new_value2"
        }
    }

    Example response:
    {
        "message": "Filter updated successfully"
    }

    If the filter name does not exist, the response will be:
    {
        "message": "Filter not found"
    }
    """
    filter_data = request.json
    conditions = filter_data.get('conditions')

    if filter_name not in filters:
        return {"message": "Filter not found"}, 404

    filters[filter_name] = conditions
    return {"message": "Filter updated successfully"}


@app.route('/filters/<filter_name>', methods=['DELETE'])
def delete_filter(filter_name):
    """
    Delete a custom filter.

    This method deletes an existing custom filter by its name.

    Example response:
    {
        "message": "Filter deleted successfully"
    }

    If the filter name does not exist, the response will be:
    {
        "message": "Filter not found"
    }
    """
    if filter_name not in filters:
        return {"message": "Filter not found"}, 404

    del filters[filter_name]
    return {"message": "Filter deleted successfully"}


@app.route('/filters', methods=['GET'])
def get_all_filters():
    """
    Get all custom filters.

    This method returns a list of all the custom filters.

    Example response:
    {
        "filters": [
            {
                "name": "filter1",
                "conditions": {
                    "field1": "value1",
                    "field2": "value2"
                }
            },
            {
                 "name": "filter2",
                 "conditions": {
                     "field3": "value3",
                     "field4": "value4"
                 }
            }
        ]
    }
    """
    return {"filters": filters}


@app.route('/filters/<filter_name>', methods=['GET'])
def get_filter(filter_name):
    """
    Get a specific custom filter.

    This method returns the details of a specific custom filter by its name.

    Example response:
    {
        "filter": {
            "name": "filter1",
            "conditions": {
                "field1": "value1",
                "field2": "value2"
            }
        }
    }

    If the filter name does not exist, the response will be:
    {
        "message": "Filter not found"
    }
    """
    if filter_name not in filters:
        return {"message": "Filter not found"}, 404

    return {"filter": {filter_name: filters[filter_name]}}


if __name__ == '__main__':
    app.run()
```

