def longest_common_subsequence(str1, str2):
    """
    Find the longest common subsequence of two strings using backtracking.

    Args:
        str1 (str): The first string.
        str2 (str): The second string.

    Returns:
        str: The longest common subsequence of the two strings.
    """
    def backtrack(i, j):
        if i == 0 or j == 0:
            return ''

        if str1[i - 1] == str2[j - 1]:
            return backtrack(i - 1, j - 1) + str1[i - 1]

        if dp[i - 1][j] > dp[i][j - 1]:
            return backtrack(i - 1, j)
        else:
            return backtrack(i, j - 1)

    # Initialize the dynamic programming table
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dynamic programming table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack to find the longest common subsequence
    return backtrack(m, n)
```

