            mid = (node.start + node.end) // 2

            if end <= mid:
                return count_substrings(node.left_child, start, end)
            elif start > mid:
                return count_substrings(node.right_child, start, end)
            else:
                count_left = count_substrings(node.left_child, start, mid)
                count_right = count_substrings(node.right_child, mid + 1, end)
                return count_left + count_right

        return count_substrings(self.root, start, end)
