class Node:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.children = {}


class SuffixTree:
    def __init__(self, text):
        self.root = Node(None, None)
        self.text = text
        self.build()

    def build(self):
        for i in range(len(self.text)):
            suffix = self.text[i:]
            current = self.root
            for char in suffix:
                if char not in current.children:
                    current.children[char] = Node(i, None)
                current = current.children[char]
            current.end = i

    def longest_non_repeating_substring(self):
        max_length = 0
        substring_end = 0
        stack = [(node, len(node.children)) for node in self.root.children.values()]

        while stack:
            current_node, num_children = stack[-1]
            stack[-1] = (current_node, num_children - 1)

            if num_children == 0:
                stack.pop()
                continue

            substring_length = current_node.end - current_node.start

            if num_children == 1 and substring_length > max_length:
                max_length = substring_length
                substring_end = current_node.end

            for child in current_node.children.values():
                stack.append((child, len(child.children)))

        return self.text[substring_end - max_length + 1:substring_end + 1]


def find_longest_non_repeating_substring(text):
    suffix_tree = SuffixTree(text)
    return suffix_tree.longest_non_repeating_substring()


