class WeightedGraph:
    def __init__(self):
        self.edges = {}

    def add_edge(self, node1, node2, weight):
        """
        Adds a weighted edge between two nodes in the graph.

        Parameters:
        - node1: The first node.
        - node2: The second node.
        - weight: The weight of the edge between the nodes.

        Returns:
        None
        """
        if node1 not in self.edges:
            self.edges[node1] = {}
        if node2 not in self.edges:
            self.edges[node2] = {}
        self.edges[node1][node2] = weight
        self.edges[node2][node1] = weight

    def detect_cycles(self):
        """
        Detects cycles in the weighted graph using depth-first search (DFS).

        Returns:
        - True if a cycle is found.
        - False if no cycle is found.
        """
        visited = set()

        def dfs(node, parent):
            # Mark the current node as visited
            visited.add(node)

            # Iterate over the neighbors of the current node
            for neighbor in self.edges[node]:
                # If the neighbor is already visited and it's not the parent of current node,
                # then a cycle is found
                if neighbor in visited and neighbor != parent:
                    return True

                # If the neighbor is not visited, recursively call the DFS function on it
                if neighbor not in visited:
                    if dfs(neighbor, node):
                        return True

            return False

        # Call the DFS function on each unvisited node in the graph
        for node in self.edges:
            if node not in visited:
                if dfs(node, None):
                    return True

        return False
```

