def train_naive_bayes(training_data):
    """
    Train a Naive Bayes classifier for sentiment analysis.

    Parameters:
    training_data (list): A list of tuples containing the preprocessed training data.
                          Each tuple should have the form (words, label),
                          where 'words' is a list of tokenized words and 'label' is the sentiment label.

    Returns:
    dict: A dictionary representing the trained Naive Bayes classifier.
          The dictionary has the following structure:
          {
              'priors': {
                  'positive': <prior probability of positive sentiment>,
                  'negative': <prior probability of negative sentiment>
              },
              'word_counts': {
                  'positive': {
                      <word_1>: <count_of_word_1_in_positive_sentences>,
                      <word_2>: <count_of_word_2_in_positive_sentences>,
                      ...
                  },
                  'negative': {
                      <word_1>: <count_of_word_1_in_negative_sentences>,
                      <word_2>: <count_of_word_2_in_negative_sentences>,
                      ...
                  },
              },
              'total_words': {
                  'positive': <total words in positive sentences>,
                  'negative': <total words in negative sentences>
              }
          }
    """

    # Initialize the required dictionaries and variables
    priors = defaultdict(int)
    word_counts = {'positive': defaultdict(int), 'negative': defaultdict(int)}
    total_words = {'positive': 0, 'negative': 0}

    # Count the occurrences of each word in positive and negative sentences
    for words, label in training_data:
        priors[label] += 1
        for word in words:
            word_counts[label][word] += 1
            total_words[label] += 1

    # Calculate the prior probabilities
    total_sentences = sum(priors.values())
    priors = {label: count / total_sentences for label, count in priors.items()}

    # Return the trained Naive Bayes classifier
    return {'priors': priors, 'word_counts': word_counts, 'total_words': total_words}


def predict_sentiment(sentence, classifier):
    """
    Predict the sentiment label of a sentence using a trained Naive Bayes classifier.

    Parameters:
    sentence (list): A list of tokenized words representing the sentence.
    classifier (dict): A dictionary representing the trained Naive Bayes classifier.

    Returns:
    str: The predicted sentiment label ('positive' or 'negative').
    """

    # Initialize the required variables
    priors = classifier['priors']
    word_counts = classifier['word_counts']
    total_words = classifier['total_words']
    vocabulary = set(list(word_counts['positive'].keys()) + list(word_counts['negative'].keys()))

    # Calculate the log probabilities of each sentiment label given the sentence
    log_probs = {}
    for label in priors.keys():
        log_prob = math.log(priors[label])
        for word in sentence:
            log_prob += math.log((word_counts[label][word] + 1) / (total_words[label] + len(vocabulary)))
        log_probs[label] = log_prob

    # Return the sentiment label with the highest log probability
    return max(log_probs, key=log_probs.get)
```

