class SegmentTree:
    def __init__(self, arr):
        self.tree = [0] * (4 * len(arr))
        self.build(arr, 0, 0, len(arr) - 1)

    def build(self, arr, node, start, end):
        if start == end:
            self.tree[node] = arr[start]
        else:
            mid = (start + end) // 2
            self.build(arr, 2 * node + 1, start, mid)
            self.build(arr, 2 * node + 2, mid + 1, end)
            self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]

    def query(self, node, start, end, k):
        if start == end:
            return start

        mid = (start + end) // 2
        left_sum = self.tree[2 * node + 1]

        if left_sum >= k:
            return self.query(2 * node + 1, start, mid, k)
        else:
            return self.query(2 * node + 2, mid + 1, end, k - left_sum)

    def find_kth_smallest(self, arr, k, n):
        self.build(arr, 0, 0, n - 1)
        return self.query(0, 0, n - 1, k)

def find_kth_smallest_element(arr, k):
    """
    Finds the kth smallest element in a given range.

    Args:
    - arr: A list of integers representing the range.
    - k: An integer representing the kth position of the smallest element.

    Returns:
    - An integer representing the kth smallest element.
    """

    n = len(arr)
    tree = SegmentTree(arr)
    return tree.find_kth_smallest(arr, k, n)
