class SuffixTreeNode:
    def __init__(self):
        self.children = {}
        self.indices = []

    def add_suffix(self, suffix, index):
        self.indices.append(index)
        if len(suffix) > 0:
            first_char = suffix[0]
            if first_char not in self.children:
                self.children[first_char] = SuffixTreeNode()
            self.children[first_char].add_suffix(suffix[1:], index)

    def search(self, query):
        if len(query) == 0:
            return self.indices

        first_char = query[0]
        if first_char in self.children:
            return self.children[first_char].search(query[1:])
        else:
            return []

class SuffixTree:
    def __init__(self):
        self.root = SuffixTreeNode()

    def construct(self, string):
        for i in range(len(string)):
            self.root.add_suffix(string[i:], i)

    def search(self, query):
        return self.root.search(query)
