class KnightTour:
    def __init__(self, n):
        self.n = n
        self.board = [[-1] * n for _ in range(n)]  # Initialize the n x n chess board
        self.moves = [
            (2, 1), (1, 2), (-1, 2), (-2, 1),  # Possible knight moves
            (-2, -1), (-1, -2), (1, -2), (2, -1)
        ]

    def is_valid_move(self, x, y):
        # Check if the move is within the board boundaries and if the square is unvisited
        return 0 <= x < self.n and 0 <= y < self.n and self.board[x][y] == -1

    def find_shortest_path(self, start_x, start_y):
        self.board[start_x][start_y] = 0  # Mark the starting square as visited
        path_len = 1

        if self._find_shortest_path_helper(start_x, start_y, path_len):
            return self.board
        else:
            return None

    def _find_shortest_path_helper(self, x, y, path_len):
        if path_len == self.n ** 2:  # Base case: All squares have been visited
            return True

        # Try all possible moves from the current position
        for move in self.moves:
            next_x = x + move[0]
            next_y = y + move[1]

            if self.is_valid_move(next_x, next_y):
                self.board[next_x][next_y] = path_len  # Mark the next square as visited

                if self._find_shortest_path_helper(next_x, next_y, path_len + 1):
                    return True

                self.board[next_x][next_y] = -1  # Backtracking: Unmark the square

        return False


